import java.io.*; import java.util.*; class Result { private static int[][] pref; private static long[] fact, invFact; private static final int MOD = 1000000007; public static void initialize(String s) { int n = s.length(); pref = new int[n + 1][26]; for (int i = 0; i < n; i++) { System.arraycopy(pref[i], 0, pref[i + 1], 0, 26); pref[i + 1][s.charAt(i) - 'a']++; } fact = new long[n + 1]; invFact = new long[n + 1]; fact[0] = 1; for (int i = 1; i <= n; i++) fact[i] = (fact[i - 1] * i) % MOD; invFact[n] = power(fact[n], MOD - 2); for (int i = n - 1; i >= 0; i--) invFact[i] = (invFact[i + 1] * (i + 1)) % MOD; } private static long power(long base, long exp) { long res = 1; base %= MOD; while (exp > 0) { if (exp % 2 == 1) res = (res * base) % MOD; base = (base * base) % MOD; exp /= 2; } return res; } public static int answerQuery(int l, int r) { int[] counts = new int[26]; int oddCount = 0; int totalPairs = 0; for (int i = 0; i < 26; i++) { counts[i] = pref[r][i] - pref[l - 1][i]; if (counts[i] % 2 != 0) oddCount++; totalPairs += counts[i] / 2; } long ans = fact[totalPairs]; for (int i = 0; i < 26; i++) { if (counts[i] / 2 > 0) ans = (ans * invFact[counts[i] / 2]) % MOD; } if (oddCount > 0) ans = (ans * oddCount) % MOD; return (int) ans; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(System.out)); String s = bufferedReader.readLine(); Result.initialize(s); int q = Integer.parseInt(bufferedReader.readLine().trim()); for (int i = 0; i < q; i++) { String[] firstMultipleInput = bufferedReader.readLine().split(" "); int l = Integer.parseInt(firstMultipleInput[0]); int r = Integer.parseInt(firstMultipleInput[1]); bufferedWriter.write(String.valueOf(Result.answerQuery(l, r))); bufferedWriter.newLine(); } bufferedReader.close(); bufferedWriter.close(); } }